from PIL import Image
import numpy as np
im=Image.open('/app/target.png').convert('L')
a=np.array(im)
for t in [80,128,180,220,240]:
 m=a<t
 H,W=m.shape; seen=np.zeros_like(m); cs=[]
 for y,x in zip(*np.nonzero(m & ~seen)):
  stack=[(y,x)]; seen[y,x]=1; pts=[]
  while stack:
   yy,xx=stack.pop(); pts.append((yy,xx))
   for y2 in range(max(0,yy-1),min(H,yy+2)):
    for x2 in range(max(0,xx-1),min(W,xx+2)):
     if m[y2,x2] and not seen[y2,x2]: seen[y2,x2]=1; stack.append((y2,x2))
  if len(pts)>2:
   ys=[p[0] for p in pts]; xs=[p[1] for p in pts]; cs.append((min(xs),min(ys),max(xs)-min(xs)+1,max(ys)-min(ys)+1,len(pts)))
 print('threshold',t,sorted(cs))
Image.open('/app/target.png').crop((300,390,725,555)).resize((850,330)).save('/app/output/crop.png')
